def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_val, product_val = 0, 1
    has_negatives = False
    has_zeros = numbers.count(0) > 0

    for num in numbers:
        sum_val += num
        if num != 0:
            product_val *= num
            if num < 0:
                has_negatives = True

    if has_zeros:
        product_val = 0
    elif has_negatives:
        product_val = -product_val

    return sum_val, product_val

