def factorize(n: int) -> List[int]:
    if n < 2:
        return []
    if n == 1:
        return []
    if is_prime(n):
        return [n]

    factors = []
    for i in range(2, int(math.sqrt(n)) + 1):
        count = 0
        while n % i == 0:
            n //= i
            count += 1
        if count > 0:
            factors.extend([i] * count)

    if n > 1:
        factors.extend([n])

    return factors

