import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = set()
    min_heap = [(grid[0][0], 0, 0)]
    visited.add((0, 0))

    while min_heap:
        cost, row, col = heapq.heappop(min_heap)
        if len(visited) == N * N:
            break

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in visited:
                visited.add((nr, nc))
                heapq.heappush(min_heap, (cost + grid[nr][nc], nr, nc))

    result = []
    for i in range(N * N):
        if i in visited:
            result.append(i + 1)
    return result

