        parts = fraction.split('/')
        if len(parts) != 2:
            return False
        numerator, denominator = parts
        if not (numerator.isdigit() and denominator.isdigit()):
            return False
        if not (numerator and denominator):
            return False
        if not (int(numerator) > 0 and int(denominator) > 0):
            return False
        return True

    def parse_fraction(fraction):
        parts = fraction.split('/')
        return int(parts[0]), int(parts[1])

    def simplify_fraction(numerator, denominator):
        while denominator != 1:
            if numerator < denominator:
                break
            if numerator % denominator == 0:
                numerator //= denominator
                denominator = 1
            else:
                numerator, denominator = denominator, numerator % denominator
        return numerator, denominator

    if not is_valid_fraction(x) or not is_valid_fraction(n):
        return False

    x_numerator, x_denominator = parse_fraction(x)
    n_numerator, n_denominator = parse_fraction(n)

    simplified_numerator = x_numerator * n_numerator
    simplified_denominator = x_denominator * n_denominator

    simplified_numerator, simplified_denominator = simplify_fraction(simplified_numerator, simplified_denominator)

    return simplified_denominator == 1

