def eat(number, need, remaining):
    if number < 0 or need < 0 or remaining < 0:
        return [0, 0]
    if number > need:
        number = need
    total_eaten = max(number, need)
    if remaining < total_eaten:
        total_eaten = remaining
        remaining = 0
    else:
        remaining -= total_eaten
    return [number + total_eaten, remaining]

